-- Importacion inicial real generada localmente.

-- No subir este archivo a GitHub.

begin;

create temp table import_employees (employee_number text, full_name text, area text, sector text, role_title text, location text, source text, is_active boolean) on commit drop;

create temp table import_vehicles (domain text, internal_code text, model text, vehicle_type text, company text, fleet_type text, area text, sector text, responsible text, equipment_description text, year integer, odometer integer, status vehicle_status, is_active boolean, source text, vtv date, vth date, telepass text) on commit drop;



select employee_number, full_name, area, sector, role_title, location, source, is_active from import_employees
on conflict (employee_number) do update set
  full_name = excluded.full_name,
  area = excluded.area,
  sector = excluded.sector,
  role_title = excluded.role_title,
  location = excluded.location,
  source = excluded.source,
  is_active = excluded.is_active,
  updated_at = now();




select domain, internal_code, model, vehicle_type, company, fleet_type, area, sector, responsible, equipment_description, year, coalesce(odometer, 0), status, is_active, source from import_vehicles
on conflict (domain) do update set
  internal_code = excluded.internal_code,
  model = excluded.model,
  vehicle_type = excluded.vehicle_type,
  company = excluded.company,
  fleet_type = excluded.fleet_type,
  area = excluded.area,
  sector = excluded.sector,
  responsible = excluded.responsible,
  equipment_description = excluded.equipment_description,
  year = excluded.year,
  odometer = excluded.odometer,
  status = excluded.status,
  is_active = excluded.is_active,
  source = excluded.source,
  updated_at = now();

delete from vehicle_documents
where vehicle_id in (select v.id from vehicles v join import_vehicles i on i.domain = v.domain)
and document_type in ('VTV', 'VTH', 'Telepase');

select v.id, 'VTV', i.vtv, case when i.vtv is null then 'sin_fecha' else 'vigente' end, 'Importado desde Excel vehicular'
from import_vehicles i join vehicles v on v.domain = i.domain
where i.vtv is not null;

select v.id, 'VTH', i.vth, case when i.vth is null then 'sin_fecha' else 'vigente' end, 'Importado desde Excel vehicular'
from import_vehicles i join vehicles v on v.domain = i.domain
where i.vth is not null;

select v.id, 'Telepase', i.telepass, 'registrado', 'Importado desde Excel vehicular'
from import_vehicles i join vehicles v on v.domain = i.domain
where i.telepass is not null and i.telepass <> '';


create temp table import_equipment (domain text, equipment_name text, expected boolean, present boolean, expires_at date, notes text) on commit drop;



delete from vehicle_equipment
where vehicle_id in (select v.id from vehicles v join import_equipment i on i.domain = v.domain);

select v.id, i.equipment_name, i.expected, i.present, i.expires_at, i.notes
from import_equipment i join vehicles v on v.domain = i.domain;


create temp table import_repairs (domain text, status maintenance_status, maintenance_type text, provider text, workshop text, detail text, entered_at date, retired_at date, notes text) on commit drop;



delete from maintenance_records
where vehicle_id in (select v.id from vehicles v join import_repairs i on i.domain = v.domain)
and maintenance_type = 'Historico importado';

select v.id, i.status, i.maintenance_type, i.provider, i.workshop, i.detail, i.entered_at, i.retired_at, i.notes
from import_repairs i join vehicles v on v.domain = i.domain;


commit;

-- Resumen: 603 empleados, 207 vehiculos, 288 equipamientos, 1471 reparaciones.